INSERT OR IGNORE INTO "solution" VALUES(7,1,'Real-Time Threat Detection & Monitoring','Continuous AI surveillance of your network infrastructure. Anomalies, intrusions, and zero-day threats identified and flagged before they escalate into full breaches using behavioural analysis.','bi-shield-exclamation',1);
INSERT OR IGNORE INTO "solution" VALUES(8,1,'Predictive System Maintenance','Machine learning models forecast system failures and security gaps before they occur, keeping your infrastructure resilient, available, and ahead of threats at all times.','bi-cpu',2);
INSERT OR IGNORE INTO "solution" VALUES(9,1,'AI-Powered Advisory Intelligence','Executive-level threat briefings generated by AI — translating complex cyber risk data into clear, actionable, boardroom-ready insights tailored to your organisation''s risk profile.','bi-lightbulb',3);
INSERT OR IGNORE INTO "solution" VALUES(10,1,'Compliance & Governance Automation','AI maps your compliance posture against POPIA, GDPR, and ISO 27001 simultaneously, surfaces gaps, and auto-generates remediation documentation to keep you audit-ready.','bi-clipboard2-check',4);
INSERT OR IGNORE INTO "solution" VALUES(11,1,'Incident Response Orchestration','When a breach occurs, our AI deploys rapid response playbooks automatically, containing, investigating, and remediating security incidents while minimising operational downtime.','bi-activity',5);
INSERT OR IGNORE INTO "solution" VALUES(12,1,'Rapid Digital Infrastructure Prototyping','AI-assisted design and deployment of secure digital infrastructure for SMEs and government agencies across Southern Africa, from architecture to live environment in days, not months.','bi-lightning-charge',8);
INSERT OR IGNORE INTO "testimonial" VALUES(2,1,'Kagiso Molefe','IT Director at Debswana Diamond Company',5,'CyberNova''s incident response team was on-site within hours of our ransomware attack. Their composure under pressure and technical precision were remarkable. They contained the breach, restored our systems, and hardened our entire network architecture. We haven''t had a single incident in 18 months since.','2026-05-06 20:29:38',1);
INSERT OR IGNORE INTO "testimonial" VALUES(3,1,'Refilwe Setlhare','Chief Risk Officer at First National Bank Botswana',5,'We engaged CyberNova for a penetration test and were honestly alarmed by what they uncovered in our authentication layer. Their findings were delivered clearly, prioritised by risk, and remediated ahead of schedule. Phishing-related account compromises dropped by over 90% following their intervention.','2026-05-06 20:30:02',1);
INSERT OR IGNORE INTO "testimonial" VALUES(4,1,'Tumelo Kgathi','Head of ICT at Botswana Electoral Commission',5,'Securing our election infrastructure was a matter of national significance. CyberNova approached the engagement with the seriousness it deserved. Their team hardened our systems across 47 district offices and monitored our network in real time on election day. Zero incidents. We have complete confidence in their capabilities.','2026-05-06 20:30:30',1);
INSERT OR IGNORE INTO "testimonial" VALUES(5,1,'Lesego Dube','Operations Manager at Mascom Wireless',4,'SIM swap fraud was costing us and our customers significantly before CyberNova stepped in. Their fraud detection model has transformed how we handle high-risk swap requests. Cases dropped from nearly 50 per month to fewer than 3. The monthly threat intelligence briefings they provide keep our team ahead of emerging threats.','2026-05-06 20:30:55',1);
INSERT OR IGNORE INTO "testimonial" VALUES(6,1,'Mpho Seretse','Compliance Director at Old Mutual Southern Africa Rating: 5 stars',5,'Navigating POPIA compliance across multiple SADC jurisdictions was overwhelming until CyberNova provided a clear remediation roadmap. Their gap analysis was thorough, their communication with our board was excellent, and we achieved full compliance ahead of the enforcement deadline. Genuinely outstanding service.','2026-05-06 20:31:24',1);
INSERT OR IGNORE INTO "testimonial" VALUES(7,1,'Onkemetse Tau','CEO at Bokamoso Private Hospital',4,'Patient data security is non-negotiable in healthcare. CyberNova identified critical vulnerabilities in our records system that we had no visibility into, implemented proper access controls, and trained our entire staff. We passed our first independent security audit shortly after. I would recommend them without hesitation.','2026-05-06 20:31:54',1);
